CREATE TABLE IF NOT EXISTS plantillas_mensaje (
    id SERIAL PRIMARY KEY,
    clave VARCHAR(80) NOT NULL UNIQUE,
    nombre VARCHAR(180) NOT NULL,
    asunto_email TEXT,
    cuerpo_email TEXT NOT NULL,
    cuerpo_whatsapp TEXT NOT NULL,
    variables_ejemplo JSON NOT NULL DEFAULT '{}'::json,
    enlace_ejemplo VARCHAR(1000),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    actualizado_por_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);
-- También corrige tablas creadas previamente por SQLAlchemy, donde los
-- valores por defecto pueden no haberse creado en la base de datos.
ALTER TABLE plantillas_mensaje ALTER COLUMN activo SET DEFAULT TRUE;
ALTER TABLE plantillas_mensaje ALTER COLUMN updated_at SET DEFAULT NOW();

INSERT INTO plantillas_mensaje (clave, nombre, asunto_email, cuerpo_email, cuerpo_whatsapp, variables_ejemplo, enlace_ejemplo) VALUES
('EVENTO_AGENDA', 'Actividad de agenda', '{{accion}} actividad: {{actividad}}', 'Hola {{nombre}},\n\n{{actor}} {{accion}} una actividad relacionada con tu proceso.\n\nProceso: {{proceso}}\nActividad: {{actividad}}\nTipo: {{tipo}}\nEstado: {{estado}}\nInicio: {{inicio}}\nFin: {{fin}}\nResponsable: {{responsable}}\nDetalle: {{detalle}}', 'Hola {{nombre}} 👋\n\n{{actor}} {{accion}} una actividad de tu proceso *{{proceso}}*.\n\n📌 {{actividad}}\nTipo: {{tipo}} · Estado: {{estado}}\nInicio: {{inicio}}\nResponsable: {{responsable}}\nDetalle: {{detalle}}', '{"nombre":"María Pérez","actor":"Abogada","accion":"programó","proceso":"Proceso de ejemplo","actividad":"Audiencia inicial","tipo":"AUDIENCIA","estado":"PROGRAMADO","inicio":"15/10/2026 09:00","fin":"No indicada","responsable":"Abogada","detalle":"Audiencia virtual"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#agenda'),
('PROCESO_ACTUALIZACION', 'Actualización de proceso', 'Actualización del proceso {{proceso}}', 'Hola {{nombre}},\n\n{{actor}} {{accion}} en el proceso {{proceso}}.\n\nFecha: {{fecha}}\nDetalle: {{detalle}}\n\nEste mensaje resume un cambio relacionado con tu expediente.', 'Hola {{nombre}} 👋\n\n{{actor}} {{accion}} en tu proceso *{{proceso}}*.\n\n{{detalle}}\nFecha: {{fecha}}', '{"nombre":"María Pérez","actor":"Abogada","accion":"registró una novedad","proceso":"Proceso de ejemplo","fecha":"15/10/2026 09:00","detalle":"Información de ejemplo"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente#proceso-1'),
('ABOGADO_CREDENCIALES', 'Acceso de abogado', 'Acceso de abogado administrador', 'Hola {{nombre}},\n\nTu acceso al sistema fue creado para {{correo}}. Cambia tu contraseña temporal al iniciar sesión.', 'Hola {{nombre}} 👋\n\nTu acceso de abogado fue creado para {{correo}}. Cambia tu contraseña temporal al ingresar.', '{"nombre":"Abogada Ejemplo","correo":"abogada@example.com"}', 'https://www.alejandramunozabogada.com/gestion-procesos/auth/login'),
('CLIENTE_CREDENCIALES', 'Credenciales de cliente', 'Acceso a tus procesos', 'Hola {{nombre}},\n\n{{actor}} creó tu acceso al portal de gestión de procesos.\n\nUsuario: {{correo}}\nContraseña temporal: {{password}}\n\nAl iniciar sesión tendrás que cambiar esta contraseña. No compartas estas credenciales.\n\nCanal elegido para futuras notificaciones: {{canal}}.', 'Hola {{nombre}} 👋\n\n{{actor}} creó tu acceso al portal.\n\nUsuario: {{correo}}\nContraseña temporal: {{password}}\n\nAl ingresar tendrás que cambiarla. No compartas estas credenciales.\nCanal futuro: {{canal}}.', '{"nombre":"María Pérez","actor":"Abogada","correo":"cliente@example.com","password":"Temporal123","canal":"EMAIL"}', 'https://www.alejandramunozabogada.com/gestion-procesos/auth/login'),
('DOCUMENTO_REVISION', 'Revisión de documento', 'Documento revisado: {{documento}}', 'Hola {{nombre}},\n\n{{actor}} revisó el documento {{documento}} del proceso {{proceso}}.\n\nEstado: {{estado}}\nComentario: {{comentario}}\nFecha: {{fecha}}', 'Hola {{nombre}} 👋\n\nRevisamos el documento *{{documento}}* de *{{proceso}}*.\nEstado: {{estado}}\nComentario: {{comentario}}\nFecha: {{fecha}}', '{"nombre":"María Pérez","actor":"Abogada","documento":"soporte.pdf","proceso":"Proceso de ejemplo","estado":"APROBADO","comentario":"Sin comentarios adicionales","fecha":"15/10/2026 09:00"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente#proceso-1'),
('COMUNICACION_CLIENTE_ABOGADO', 'Mensaje de cliente al despacho', 'Mensaje de {{nombre}}: {{asunto}}', 'Hola {{nombre}},\n\n{{actor}} te envió un mensaje sobre el proceso {{proceso}}.\n\nAsunto: {{asunto}}\nFecha: {{fecha}}\nMensaje:\n{{mensaje}}', 'Hola {{nombre}} 👋\n\n{{actor}} te escribió sobre *{{proceso}}*.\n\n*{{asunto}}*\n{{mensaje}}\nFecha: {{fecha}}', '{"nombre":"Abogada Ejemplo","actor":"María Pérez","proceso":"Proceso de ejemplo","asunto":"Consulta","fecha":"15/10/2026 09:00","mensaje":"Mensaje de ejemplo"}', 'https://www.alejandramunozabogada.com/gestion-procesos/abogado/procesos/1/comunicaciones'),
('COMUNICACION_ABOGADO_CLIENTE', 'Comunicación del despacho al cliente', 'Nueva comunicación: {{asunto}}', 'Hola {{nombre}},\n\n{{actor}} registró una comunicación para el proceso {{proceso}}.\n\nAsunto: {{asunto}}\nFecha: {{fecha}}\nDetalle: {{mensaje}}', 'Hola {{nombre}} 👋\n\nTienes una nueva comunicación sobre *{{proceso}}*.\n\n*{{asunto}}*\n{{mensaje}}\nFecha: {{fecha}}', '{"nombre":"María Pérez","actor":"Abogada","proceso":"Proceso de ejemplo","asunto":"Actualización","fecha":"15/10/2026 09:00","mensaje":"Mensaje de ejemplo"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#comunicaciones'),
('COLABORADOR_AGREGADO', 'Abogado agregado al proceso', 'Te agregaron al proceso {{proceso}}', 'Hola {{nombre}},\n\n{{actor}} te agregó como {{permiso}} en el proceso {{proceso}}.\n\nResponsable: {{responsable}}\nPermiso: {{permiso}}', 'Hola {{nombre}} 👋\n\n{{actor}} te agregó como {{permiso}} al proceso *{{proceso}}*.\nResponsable: {{responsable}}', '{"nombre":"Abogada Ejemplo","actor":"Abogada","permiso":"colaborador interno","proceso":"Proceso de ejemplo","responsable":"Abogada responsable"}', 'https://www.alejandramunozabogada.com/gestion-procesos/abogado/procesos/1'),
('ACTUACION_NOTIFICADA', 'Actuación judicial informada', 'Actualización del proceso {{proceso}}', 'Hola {{nombre}},\n\n{{actor}} te informa una actuación del proceso {{proceso}}.\n\nRadicado: {{radicado}}\nFecha: {{fecha}}\nActuación: {{actuacion}}\nAnotación: {{anotacion}}\nComentarios: {{comentarios}}', 'Hola {{nombre}} 👋\n\nHay una novedad en *{{proceso}}*.\nRadicado: {{radicado}}\nFecha: {{fecha}}\nActuación: {{actuacion}}\nAnotación: {{anotacion}}\nComentario: {{comentarios}}', '{"nombre":"María Pérez","actor":"Abogada","proceso":"Proceso de ejemplo","radicado":"05001311001220250035600","fecha":"15/10/2026","actuacion":"Auto admite demanda","anotacion":"Notificación registrada","comentarios":"Te informamos esta novedad"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#actividad'),
('SOLICITUD_DOCUMENTO', 'Solicitud de documento', 'Documento solicitado: {{proceso}}', 'Hola {{nombre}},\n\n{{actor}} solicitó un documento para el proceso {{proceso}}.\n\nSolicitud: {{solicitud}}\nInstrucciones: {{instrucciones}}\nFecha límite: {{fecha_limite}}\nFecha de solicitud: {{fecha}}', 'Hola {{nombre}} 👋\n\nNecesitamos un documento para *{{proceso}}*.\nSolicitud: {{solicitud}}\nInstrucciones: {{instrucciones}}\nFecha límite: {{fecha_limite}}', '{"nombre":"María Pérez","actor":"Abogada","proceso":"Proceso de ejemplo","solicitud":"Certificado","instrucciones":"Carga el documento en PDF","fecha_limite":"20/10/2026","fecha":"15/10/2026"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#documentos'),
('DOCUMENTO_RECIBIDO', 'Documento recibido', 'Documento recibido: {{documento}}', 'Hola {{nombre}},\n\n{{actor}} cargó un documento para el proceso {{proceso}}.\n\nDocumento: {{documento}}\nSolicitud: {{solicitud}}\nTipo: {{tipo}}\nFecha de carga: {{fecha}}', 'Hola {{nombre}} 👋\n\n{{actor}} cargó un documento para *{{proceso}}*.\nDocumento: {{documento}}\nSolicitud: {{solicitud}}\nFecha: {{fecha}}', '{"nombre":"Abogada Ejemplo","actor":"María Pérez","proceso":"Proceso de ejemplo","documento":"certificado.pdf","solicitud":"Certificado","tipo":"application/pdf","fecha":"15/10/2026"}', 'https://www.alejandramunozabogada.com/gestion-procesos/abogado/procesos/1/documentos'),
('TAREA_ACCION', 'Cambios de tareas', '{{accion}}: {{tarea}}', 'Hola {{nombre}},\n\n{{actor}} {{accion}}.\n\nTarea: {{tarea}}\nDetalle: {{detalle}}\nEstado: {{estado}}\nPrioridad: {{prioridad}}\nFecha límite: {{fecha_limite}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}', 'Hola {{nombre}} 👋\n\n{{actor}} {{accion}}.\n\n*Tarea: {{tarea}}*\n{{detalle}}\nEstado: {{estado}} · Prioridad: {{prioridad}}\nFecha límite: {{fecha_limite}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}', '{"nombre":"María Pérez","actor":"Abogada","accion":"actualizó la tarea","tarea":"Preparar documentos","detalle":"Revisar soportes","estado":"PENDIENTE","prioridad":"ALTA","fecha_limite":"20/10/2026","proceso":"Proceso de ejemplo","radicado":"05001311001220250035600","actuacion":"No asociada"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/tareas?tarea=1#tarea-1'),
('SUBTAREA_ASIGNADA', 'Subtarea asignada', 'Nueva subtarea asignada', '{{actor}} te asignó la subtarea {{subtarea}} de la tarea {{tarea}}.', 'Hola {{nombre}} 👋\n\n{{actor}} te asignó la subtarea *{{subtarea}}* de la tarea *{{tarea}}*.', '{"nombre":"María Pérez","actor":"Abogada","subtarea":"Reunir anexos","tarea":"Preparar documentos"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/tareas?tarea=1#tarea-1'),
('RECORDATORIO_TAREA', 'Recordatorio de tarea', 'Recordatorio de tarea: {{tarea}}', 'Hola {{nombre}},\n\nRecuerda revisar o completar la tarea {{tarea}}.\n\nEstado: {{estado}}\nPrioridad: {{prioridad}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}\nDetalle: {{detalle}}\nVencimiento: {{fecha_limite}}\nAviso: {{anticipacion}}', 'Hola {{nombre}} 👋\n\n⏰ Recordatorio de la tarea *{{tarea}}*.\nEstado: {{estado}} · Prioridad: {{prioridad}}\nVencimiento: {{fecha_limite}}\nAviso: {{anticipacion}}\nProceso: {{proceso}}\nDetalle: {{detalle}}', '{"nombre":"María Pérez","tarea":"Preparar documentos","estado":"PENDIENTE","prioridad":"ALTA","proceso":"Proceso de ejemplo","radicado":"No asociado","actuacion":"No asociada","detalle":"Revisar soportes","fecha_limite":"20/10/2026","anticipacion":"24 horas antes"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/tareas?tarea=1#tarea-1'),
('REACTIVACION_TAREA', 'Tarea pendiente al reactivar usuario', 'Tarea pendiente tras reactivar tu cuenta', 'Hola {{nombre}},\n\nTu cuenta está activa nuevamente y tienes una tarea pendiente.\n\nTarea: {{tarea}}\nProceso: {{proceso}}\nEstado: {{estado}}\nFecha límite: {{fecha_limite}}', 'Hola {{nombre}} 👋\n\nTu cuenta está activa de nuevo y tienes pendiente la tarea *{{tarea}}*.\nProceso: {{proceso}}\nEstado: {{estado}} · Vence: {{fecha_limite}}', '{"nombre":"María Pérez","tarea":"Preparar documentos","proceso":"Proceso de ejemplo","estado":"PENDIENTE","fecha_limite":"20/10/2026"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/tareas?tarea=1#tarea-1'),
('REACTIVACION_EVENTO', 'Actividad próxima al reactivar usuario', 'Actividad próxima tras reactivar tu cuenta', 'Hola {{nombre}},\n\nTu cuenta está activa nuevamente y tienes una actividad próxima.\n\nActividad: {{actividad}}\nProceso: {{proceso}}\nTipo: {{tipo}}\nFecha: {{fecha}}\nDetalle: {{descripcion}}', 'Hola {{nombre}} 👋\n\nTu cuenta está activa de nuevo y tienes una actividad próxima: *{{actividad}}*.\nProceso: {{proceso}} · {{tipo}}\nFecha: {{fecha}}\n{{descripcion}}', '{"nombre":"María Pérez","actividad":"Audiencia inicial","proceso":"Proceso de ejemplo","tipo":"AUDIENCIA","fecha":"20/10/2026","descripcion":"Audiencia virtual"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#agenda'),
('REACTIVACION_COMUNICACION', 'Comunicación pendiente al reactivar usuario', 'Comunicación pendiente: {{asunto}}', 'Hola {{nombre}},\n\nTu cuenta está activa nuevamente y tienes una comunicación pendiente en {{proceso}}.\n\nAsunto: {{asunto}}\nFecha: {{fecha}}\nMensaje: {{mensaje}}', 'Hola {{nombre}} 👋\n\nTienes una comunicación pendiente en *{{proceso}}*.\n*{{asunto}}* · {{fecha}}\n{{mensaje}}', '{"nombre":"María Pérez","proceso":"Proceso de ejemplo","asunto":"Actualización","fecha":"15/10/2026","mensaje":"Te compartimos una novedad"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1#comunicaciones'),
('ACTUACIONES_DIGEST', 'Novedades judiciales', 'Novedades judiciales', 'Hola {{nombre}},\n\nSe registraron novedades en tus procesos:\n\n{{novedades}}', 'Hola {{nombre}} 👋\n\nHay novedades en tus procesos:\n\n{{novedades}}', '{"nombre":"María Pérez","novedades":"Proceso: Proceso de ejemplo\nRadicado: 05001311001220250035600\nNovedades: 1"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente?radicado=1#radicado-1'),
('RESUMEN_MENSUAL', 'Resumen mensual de procesos', 'Resumen mensual de procesos ({{mes}})', '{{resumen}}', '{{resumen}}', '{"nombre":"María Pérez","mes":"Octubre 2026","resumen":"Estado consolidado de los procesos"}', NULL),
('RECUPERAR_PASSWORD', 'Recuperación de contraseña', 'Restablece tu contraseña', 'Usa el botón para elegir una nueva contraseña. El enlace vence en 20 minutos. Si no solicitaste el cambio, ignora este mensaje.', 'Usa el botón para restablecer tu contraseña; vence en 20 minutos. Si no lo solicitaste, ignora este mensaje.', '{}', 'https://www.alejandramunozabogada.com/gestion-procesos/auth/restablecer?token=ejemplo'),
('CODIGO_SEGURIDAD', 'Código de seguridad OTP', 'Código de seguridad de tu cuenta', 'Hola {{nombre}},\n\nTu código de seguridad es {{codigo}}. Vence en 3 minutos. Si no solicitaste este cambio, ignora este mensaje.', 'Hola {{nombre}}. Tu código de seguridad es {{codigo}}. Vence en 3 minutos. Si no solicitaste este cambio, ignora este mensaje.', '{"nombre":"María Pérez","codigo":"123456"}', NULL),
('CONTRATO_FIRMADO', 'Copia de contrato firmado', 'Copia de contrato firmado — {{proceso}}', 'Hola {{nombre}},\n\nAdjuntamos una copia del contrato firmado asociado a tu expediente {{proceso}}. También puedes consultarlo en el portal.\n\nEl documento queda disponible en la sección Documentos del expediente.', 'Hola {{nombre}} 👋\n\nTe enviamos la copia del contrato firmado de *{{proceso}}*. También está disponible en Documentos del expediente.', '{"nombre":"María Pérez","proceso":"Proceso de ejemplo"}', 'https://www.alejandramunozabogada.com/gestion-procesos/cliente/procesos/1'),
('PRUEBA_INTEGRACION', 'Prueba de integración', 'Prueba de integración', 'Mensaje de prueba solicitado por un administrador.', 'Hola, este es un mensaje de prueba solicitado por un administrador.', '{}', NULL)
ON CONFLICT (clave) DO UPDATE SET variables_ejemplo = replace(replace(plantillas_mensaje.variables_ejemplo::text, '09:00 UTC', '04:00'), ' UTC', '')::json WHERE plantillas_mensaje.variables_ejemplo::text LIKE '% UTC%';


UPDATE plantillas_mensaje
SET enlace_ejemplo = CASE clave
    WHEN 'COMUNICACION_CLIENTE_ABOGADO' THEN 'https://www.alejandramunozabogada.com/gestion-procesos/abogado/procesos/1/comunicaciones'
    WHEN 'DOCUMENTO_RECIBIDO' THEN 'https://www.alejandramunozabogada.com/gestion-procesos/abogado/procesos/1/documentos'
END
WHERE clave IN ('COMUNICACION_CLIENTE_ABOGADO', 'DOCUMENTO_RECIBIDO');
